// again at intent for the new occurrence. The window's notice claims stay, so
// the notice and the recovery run are not given twice.
func (q *Queries) ReviveRunBudgetRefusal(ctx context.Context, arg ReviveRunBudgetRefusalParams) (RunBudgetRefusal, error) {
	row := q.db.QueryRow(ctx, reviveRunBudgetRefusal,
		arg.ID,
		arg.Status,
		arg.OccurrenceActivityID,
		arg.Blocked,
		arg.AgentID,
		arg.Trigger,
		arg.StateReason,
		arg.State,
		arg.TaintIds,
		arg.ActorUserID,
		arg.TriggerCommentID,
	)
	var i RunBudgetRefusal
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.WindowID,
		&i.Status,
		&i.OccurrenceActivityID,
		&i.Blocked,
		&i.AgentID,
		&i.Trigger,
		&i.State,
		&i.StateReason,
		&i.HookPhase,
		&i.HookReason,
		&i.ActionID,
		&i.ResumeWindowID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.HookGeneration,
		&i.TaintIds,
		&i.TaskID,
		&i.ActorUserID,
		&i.TriggerCommentID,
		&i.SourceWakeupID,
		&i.SourceTaskID,
	)
	return i, err
}

const setRunBudgetRefusalHook = `-- name: SetRunBudgetRefusalHook :exec
UPDATE run_budget_refusal
SET hook_phase = $1::text,
    hook_reason = $2::text,
    blocked = COALESCE($3::boolean, blocked),
    occurrence_activity_id = COALESCE($4::uuid, occurrence_activity_id),
    updated_at = now()
WHERE id = $5::uuid
`

type SetRunBudgetRefusalHookParams struct {
	HookPhase            string      `json:"hook_phase"`
	HookReason           pgtype.Text `json:"hook_reason"`
	Blocked              pgtype.Bool `json:"blocked"`
	OccurrenceActivityID pgtype.UUID `json:"occurrence_activity_id"`
	ID                   pgtype.UUID `json:"id"`
}

// Advances the hook. A NULL occurrence keeps the stored one.
func (q *Queries) SetRunBudgetRefusalHook(ctx context.Context, arg SetRunBudgetRefusalHookParams) error {
	_, err := q.db.Exec(ctx, setRunBudgetRefusalHook,
		arg.HookPhase,
		arg.HookReason,
		arg.Blocked,
		arg.OccurrenceActivityID,
		arg.ID,
	)
	return err
}

const setRunBudgetRefusalSource = `-- name: SetRunBudgetRefusalSource :exec
UPDATE run_budget_refusal
SET source_wakeup_id = $1::uuid, source_task_id = $2::uuid
WHERE id = $3::uuid
`

type SetRunBudgetRefusalSourceParams struct {
	SourceWakeupID pgtype.UUID `json:"source_wakeup_id"`
	SourceTaskID   pgtype.UUID `json:"source_task_id"`
	ID             pgtype.UUID `json:"id"`
}

// The native source a refusal stopped (CHE-2860): a derived wakeup rule or a
// failed run. Written with the insert or the revive, NULLs included.
func (q *Queries) SetRunBudgetRefusalSource(ctx context.Context, arg SetRunBudgetRefusalSourceParams) error {
	_, err := q.db.Exec(ctx, setRunBudgetRefusalSource, arg.SourceWakeupID, arg.SourceTaskID, arg.ID)
	return err
}

const supersedeRunBudgetRefusalsExcept = `-- name: SupersedeRunBudgetRefusalsExcept :exec
UPDATE run_budget_refusal
SET state = 'superseded', state_reason = 'later_window',
    hook_phase = CASE WHEN hook_phase IN ('intent', 'blocked') THEN 'retired' ELSE hook_phase END,
    hook_reason = CASE WHEN hook_phase IN ('intent', 'blocked') THEN 'later_window' ELSE hook_reason END,
    updated_at = now()
WHERE issue_id = $1 AND id <> $2 AND state IN ('open', 'resume_pending', 'still_blocked')
`

type SupersedeRunBudgetRefusalsExceptParams struct {
	IssueID pgtype.UUID `json:"issue_id"`
	ID      pgtype.UUID `json:"id"`
}

// A refusal for a later window ends every earlier non-terminal refusal of the
// issue and its unfinished hook (P2r supersession a).
func (q *Queries) SupersedeRunBudgetRefusalsExcept(ctx context.Context, arg SupersedeRunBudgetRefusalsExceptParams) error {
	_, err := q.db.Exec(ctx, supersedeRunBudgetRefusalsExcept, arg.IssueID, arg.ID)
	return err
}

const supersedeRunBudgetRefusalsOnStatusChange = `-- name: SupersedeRunBudgetRefusalsOnStatusChange :exec
UPDATE run_budget_refusal
SET state = 'superseded', state_reason = 'status_moved',
    hook_phase = CASE WHEN hook_phase IN ('intent', 'blocked') THEN 'retired' ELSE hook_phase END,
    hook_reason = CASE WHEN hook_phase IN ('intent', 'blocked') THEN 'status_moved' ELSE hook_reason END,
    updated_at = now()
WHERE issue_id = $1 AND state IN ('open', 'resume_pending', 'still_blocked')
`

// A status move starts its own work: every non-terminal refusal of the issue
// ends, and so does its unfinished hook (P2r supersession b).
func (q *Queries) SupersedeRunBudgetRefusalsOnStatusChange(ctx context.Context, issueID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, supersedeRunBudgetRefusalsOnStatusChange, issueID)
	return err
}

const taintBudgetRecoveryRuns = `-- name: TaintBudgetRecoveryRuns :exec
UPDATE agent_task_queue SET taint_ids = $1::text[]
WHERE issue_id = $2::uuid AND task_kind = 'budget_recovery'
  AND status IN ('queued', 'dispatched', 'waiting_local_directory', 'running')
`

type TaintBudgetRecoveryRunsParams struct {
	Taint   []string    `json:"taint"`
	IssueID pgtype.UUID `json:"issue_id"`
}

// A requester that joined a hook after its notice committed: the recovery run
// already exists, so it takes the requester's taint, whether it is still queued
// waiting for a local directory, or already started (the task trigger unions it with what the run has, and a
// started run reads its taint on every call).
func (q *Queries) TaintBudgetRecoveryRuns(ctx context.Context, arg TaintBudgetRecoveryRunsParams) error {
	_, err := q.db.Exec(ctx, taintBudgetRecoveryRuns, arg.Taint, arg.IssueID)
	return err
}

const unionTaskTaint = `-- name: UnionTaskTaint :exec
UPDATE agent_task_queue
SET taint_ids = ARRAY(SELECT DISTINCT t FROM unnest(taint_ids || $1::text[]) AS t ORDER BY t)
WHERE id = $2::uuid AND NOT taint_ids @> $1::text[]
`

type UnionTaskTaintParams struct {
	Taint []string    `json:"taint"`
	ID    pgtype.UUID `json:"id"`
}

// The run a refusal ended on carries the refusal's taint (CHE-2860). Monotonic:
// the task keeps what it has (the agent_task_inherit_taint trigger unions it
// again), so a join never makes a run cleaner.
func (q *Queries) UnionTaskTaint(ctx context.Context, arg UnionTaskTaintParams) error {
	_, err := q.db.Exec(ctx, unionTaskTaint, arg.Taint, arg.ID)
	return err
}
